import{_ as r,a0 as o,w as d,s as p,ao as n,I as e,x as i,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用子模組和子樹來管理 Git 項目 | LCTT x X-CMD","titleTemplate":false,"description":"使用子模組和子樹來管理 Git 項目 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用子模組和子樹來管理 Git 項目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用子模組和子樹來管理 Git 項目 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200506 Managing Git projects with submodules and subtrees","title":"使用子模組和子樹來管理 Git 項目","tag":"202005","desc":""},"relativePath":"202005/20200506 Managing Git projects with submodules and subtrees.md","filePath":"[post].md"}'),u={name:"202005/20200506 Managing Git projects with submodules and subtrees.md"};function g(h,t,b,k,m,f){const s=o("Link");return d(),p("div",null,[t[35]||(t[35]=n('<h1 id="使用子模組和子樹來管理-git-項目" tabindex="-1">使用子模組和子樹來管理 Git 項目 <a class="header-anchor" href="#使用子模組和子樹來管理-git-項目" aria-label="Permalink to “使用子模組和子樹來管理 Git 項目”">​</a></h1><blockquote><p>使用子模組和子樹來幫助你管理多個存儲庫中共有的子項目。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/23/201323myyhob22eg2y2jqt.jpg" alt=""></p><p>如果你參與了開源項目的開發，那麼你很可能已經用了 Git 來管理你的源碼。你可能遇到過有很多依賴和/或子項目的項目。你是如何管理它們的？</p><p>對於一個開源組織，要實現社區<strong>和</strong>產品的單一來源文檔和依賴管理比較棘手。文檔和項目往往會碎片化和變得冗餘，這致使它們很難維護。</p><h3 id="必要性" tabindex="-1">必要性 <a class="header-anchor" href="#必要性" aria-label="Permalink to “必要性”">​</a></h3><p>假設你想把單個項目作為一個存儲庫內的子項目，傳統的方法是把該項目複製到父存儲庫中，但是，如果你想要在多個父項目中使用同一個子項目呢？如果把子項目複製到所有父項目中，當有更新時，你都要在每個父項目中做修改，這是不太可行的。這會導致父項目中的冗餘和數據不一致，使更新和維護子項目變得很困難。</p><h3 id="git-子模組和子樹" tabindex="-1">Git 子模組和子樹 <a class="header-anchor" href="#git-子模組和子樹" aria-label="Permalink to “Git 子模組和子樹”">​</a></h3><p>如果你可以用一條命令把一個項目放進另一個項目中，會怎樣呢？如果你隨時可以把一個項目作為子項目添加到任意數目的項目中，並可以同步更新修改呢？Git 提供了這類問題的解決方案：Git <ruby>子模組<rt>submodule</rt></ruby>和 Git <ruby>子樹<rt>subtree</rt></ruby>。創建這些工具的目的是以更加模組化的水平來支持共用代碼的開發工作流，旨在 Git 存儲庫<ruby>源碼管理<rt>source-code management</rt></ruby>（SCM）與它下面的子樹之間架起一座橋樑。</p><p><img src="https://opensource.com/sites/default/files/uploads/640px-bialbero_di_casorzo.jpg" alt="Cherry tree growing on a mulberry tree" title="Cherry tree growing on a mulberry tree"></p><p><em>生長在桑樹上的櫻桃樹</em></p><p>下面是本文要詳細介紹的概念的一個真實應用場景。如果你已經很熟悉樹形結構，這個模型看起來是下面這樣：</p><p><img src="https://opensource.com/sites/default/files/subtree_0.png" alt="Tree with subtrees" title="Tree with subtrees"></p><h3 id="git-子模組是什麼" tabindex="-1">Git 子模組是什麼？ <a class="header-anchor" href="#git-子模組是什麼" aria-label="Permalink to “Git 子模組是什麼？”">​</a></h3>',14)),e("p",null,[t[1]||(t[1]=i("Git 在它默認的包中提供了子模組，子模組可以把 Git 存儲庫嵌入到其他存儲庫中。確切地説，Git 子模組指向子樹中的某次提交。下面是我 ",-1)),a(s,{href:"https://github.com/manaswinidas/Docs-test/"},{default:l(()=>[...t[0]||(t[0]=[i("Docs-test",-1)])]),_:1}),t[2]||(t[2]=i(" GitHub 存儲庫中的 Git 子模組的樣子：",-1))]),t[36]||(t[36]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/git-submodules_github.png",alt:"Git submodules screenshot",title:"Git submodules screenshot"})],-1)),e("p",null,[a(s,{href:"mailto:folder@commitId"},{default:l(()=>[...t[3]||(t[3]=[i("文件夾@提交 Id",-1)])]),_:1}),t[4]||(t[4]=i(" 格式表明這個存儲庫是一個子模組，你可以直接點擊文件夾進入該子樹。名為 ",-1)),t[5]||(t[5]=e("code",null,".gitmodules",-1)),t[6]||(t[6]=i(" 的配置文件包含所有子模組存儲庫的詳細信息。我的存儲庫的 ",-1)),t[7]||(t[7]=e("code",null,".gitmodules",-1)),t[8]||(t[8]=i(" 文件如下：",-1))]),t[37]||(t[37]=n(`<p><img src="https://opensource.com/sites/default/files/uploads/gitmodules.png" alt="Screenshot of .gitmodules file" title="Screenshot of .gitmodules file"></p><p>你可以用下面的命令在你的存儲庫中使用 Git 子模組：</p><h4 id="克隆一個存儲庫並加載子模組" tabindex="-1">克隆一個存儲庫並加載子模組 <a class="header-anchor" href="#克隆一個存儲庫並加載子模組" aria-label="Permalink to “克隆一個存儲庫並加載子模組”">​</a></h4><p>克隆一個含有子模組的存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone --recursive &lt;URL to Git repo&gt;</span></span></code></pre></div><p>如果你之前已經克隆了存儲庫，現在想加載它的子模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init</span></span></code></pre></div><p>如果有嵌套的子模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init --recursive</span></span></code></pre></div><h4 id="下載子模組" tabindex="-1">下載子模組 <a class="header-anchor" href="#下載子模組" aria-label="Permalink to “下載子模組”">​</a></h4><p>串行地連續下載多個子模組是很枯燥的工作，所以 <code>clone</code> 和 <code>submodule update</code> 會支持 <code>--jobs</code> （或 <code>-j</code>）參數：</p><p>例如，想一次下載 8 個子模組，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init --recursive -j 8</span></span>
<span class="line"><span>$ git clone --recursive --jobs 8 &lt;URL to Git repo&gt;</span></span></code></pre></div><h4 id="拉取子模組" tabindex="-1">拉取子模組 <a class="header-anchor" href="#拉取子模組" aria-label="Permalink to “拉取子模組”">​</a></h4><p>在運行或構建父項目之前，你需要確保依賴的子項目都是最新的。</p><p>拉取子模組的所有修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --remote</span></span></code></pre></div><h4 id="使用子模組創建存儲庫" tabindex="-1">使用子模組創建存儲庫： <a class="header-anchor" href="#使用子模組創建存儲庫" aria-label="Permalink to “使用子模組創建存儲庫：”">​</a></h4><p>向一個父存儲庫添加子樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule add &lt;URL to Git repo&gt;</span></span></code></pre></div><p>初始化一個已存在的 Git 子模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule init</span></span></code></pre></div><p>你也可以通過為 <code>submodule update</code> 命令添加 <code>--update</code> 參數在子模組中創建分支和追蹤提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --remote</span></span></code></pre></div><h4 id="更新子模組的提交" tabindex="-1">更新子模組的提交 <a class="header-anchor" href="#更新子模組的提交" aria-label="Permalink to “更新子模組的提交”">​</a></h4><p>上面提到過，一個子模組就是一個指向子樹中某次提交的鏈接。如果你想更新子模組的提交，不要擔心。你不需要顯式地指定最新的提交。你只需要使用通用的 <code>submodule update</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update</span></span></code></pre></div><p>就像你平時創建父存儲庫和把父存儲庫推送到 GitHub 那樣添加和提交就可以了。</p><h4 id="從一個父存儲庫中刪除一個子模組" tabindex="-1">從一個父存儲庫中刪除一個子模組 <a class="header-anchor" href="#從一個父存儲庫中刪除一個子模組" aria-label="Permalink to “從一個父存儲庫中刪除一個子模組”">​</a></h4><p>僅僅手動刪除一個子項目文件夾不會從父項目中移除這個子項目。想要刪除名為 <code>childmodule</code> 的子模組，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rm -f childmodule</span></span></code></pre></div><p>雖然 Git 子模組看起來很容易上手，但是對於初學者來説，有一定的使用門檻。</p><h3 id="git-子樹是什麼" tabindex="-1">Git 子樹是什麼？ <a class="header-anchor" href="#git-子樹是什麼" aria-label="Permalink to “Git 子樹是什麼？”">​</a></h3><p>Git <ruby>子樹<rt> subtree</rt></ruby>，是在 Git 1.7.11 引入的，讓你可以把任何存儲庫的副本作為子目錄嵌入另一個存儲庫中。它是 Git 項目可以注入和管理項目依賴的幾種方法之一。它在常規的提交中保存了外部依賴信息。Git 子樹提供了整潔的集成點，因此很容易復原它們。</p>`,34)),e("p",null,[t[11]||(t[11]=i("如果你參考 ",-1)),a(s,{href:"https://help.github.com/en/github/using-git/about-git-subtree-merges"},{default:l(()=>[...t[9]||(t[9]=[i("GitHub 提供的子樹教程",-1)])]),_:1}),t[12]||(t[12]=i("來使用子樹，那麼無論你什麼時候添加子樹，在本地都不會看到 ",-1)),t[13]||(t[13]=e("code",null,".gittrees",-1)),t[14]||(t[14]=i(" 配置文件。這讓我們很難分辨哪個是子樹，因為它們看起來很像普通的文件夾，但是它們卻是子樹的副本。默認的 Git 包中不提供帶 ",-1)),t[15]||(t[15]=e("code",null,".gittrees",-1)),t[16]||(t[16]=i(" 配置文件的 Git 子樹版本，因此如果你想要帶 ",-1)),t[17]||(t[17]=e("code",null,".gittrees",-1)),t[18]||(t[18]=i(" 配置文件的 git-subtree 命令，必須從 Git 源碼存儲庫的 ",-1)),a(s,{href:"https://github.com/git/git/tree/master/contrib/subtree"},{default:l(()=>[...t[10]||(t[10]=[i("/contrib/subtree 文件夾",-1)])]),_:1}),t[19]||(t[19]=i(" 下載 git-subtree。",-1))]),t[38]||(t[38]=n(`<p>你可以像克隆其他常規的存儲庫那樣克隆任何含有子樹的存儲庫，但由於在父存儲庫中有整個子樹的副本，因此克隆過程可能會持續很長時間。</p><p>你可以用下面的命令在你的存儲庫中使用 Git 子樹。</p><h4 id="向父存儲庫中添加一個子樹" tabindex="-1">向父存儲庫中添加一個子樹 <a class="header-anchor" href="#向父存儲庫中添加一個子樹" aria-label="Permalink to “向父存儲庫中添加一個子樹”">​</a></h4><p>想要向父存儲庫中添加一個子樹，首先你需要執行 <code>remote add</code>，之後執行 <code>subtree add</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add remote-name &lt;URL to Git repo&gt;</span></span>
<span class="line"><span>$ git subtree add --prefix=folder/ remote-name &lt;URL to Git repo&gt; subtree-branchname</span></span></code></pre></div><p>上面的命令會把整個子項目的提交歷史合併到父存儲庫。</p><h4 id="向子樹推送修改以及從子樹拉取修改" tabindex="-1">向子樹推送修改以及從子樹拉取修改 <a class="header-anchor" href="#向子樹推送修改以及從子樹拉取修改" aria-label="Permalink to “向子樹推送修改以及從子樹拉取修改”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git subtree push-all</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git subtree pull-all</span></span></code></pre></div><h3 id="你應該使用哪個" tabindex="-1">你應該使用哪個？ <a class="header-anchor" href="#你應該使用哪個" aria-label="Permalink to “你應該使用哪個？”">​</a></h3><p>任何工具都有優缺點。下面是一些可能會幫助你決定哪種最適合你的特性：</p><ul><li>Git 子模組的存儲庫佔用空間更小，因為它們只是指向子項目的某次提交的鏈接，而 Git 子樹保存了整個子項目及其提交歷史。</li><li>Git 子模組需要在服務器中可訪問，但子樹是去中心化的。</li><li>Git 子模組大量用於基於組件的開發，而 Git 子樹多用於基於系統的開發。</li></ul><p>Git 子樹並不是 Git 子模組的直接可替代項。有明確的説明來指導我們該使用哪種。如果有一個歸屬於你的外部存儲庫，使用場景是向它回推代碼，那麼就使用 Git 子模組，因為推送代碼更容易。如果你有第三方代碼，且不會向它推送代碼，那麼使用 Git 子樹，因為拉取代碼更容易。</p><p>自己嘗試使用 Git 子樹和子模組，然後在評論中留下你的使用感想。</p><hr>`,16)),e("p",null,[t[21]||(t[21]=i("via: ",-1)),a(s,{href:"https://opensource.com/article/20/5/git-submodules-subtrees"},{default:l(()=>[...t[20]||(t[20]=[i("https://opensource.com/article/20/5/git-submodules-subtrees",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=i("作者：",-1)),a(s,{href:"https://opensource.com/users/manaswinidas"},{default:l(()=>[...t[22]||(t[22]=[i("Manaswini Das",-1)])]),_:1}),t[27]||(t[27]=i(" 選題：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[23]||(t[23]=[i("lujun9972",-1)])]),_:1}),t[28]||(t[28]=i(" 譯者：",-1)),a(s,{href:"https://github.com/lxbwolf"},{default:l(()=>[...t[24]||(t[24]=[i("lxbwolf",-1)])]),_:1}),t[29]||(t[29]=i(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[25]||(t[25]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[32]||(t[32]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[30]||(t[30]=[i("LCTT",-1)])]),_:1}),t[33]||(t[33]=i(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:l(()=>[...t[31]||(t[31]=[i("Linux中國",-1)])]),_:1}),t[34]||(t[34]=i(" 榮譽推出",-1))])])}const C=r(u,[["render",g]]);export{y as __pageData,C as default};
